def transform(grid):
    h, w = len(grid), len(grid[0])
    # Complete horizontal bars encode a repeating sequence by row number.
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and all(v == row[0] for v in row)]
    if bars:
        period, palette = _period_palette(bars)
        return [[palette[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the colored diagonal tracks encode a sequence by c-r offset.
    samples = [(c - r, value)
               for r, row in enumerate(grid)
               for c, value in enumerate(row) if value != 0]
    period, palette = _period_palette(samples)
    return [[palette[(c - r) % period] for c in range(w)] for r in range(h)]
